<script setup lang="ts">
import { computed } from 'vue';import ChartBase from './ChartBase.vue';import type { EChartsCoreOption } from 'echarts/core';const props=withDefaults(defineProps<{data:Array<{date:string;level:number;detail?:string}>;months?:number;height?:number|string}>(),{months:3,height:220});const emit=defineEmits<{select:[date:string]}>();const css=(n:string)=>getComputedStyle(document.documentElement).getPropertyValue(n).trim();const iso=(value:Date)=>`${value.getFullYear()}-${String(value.getMonth()+1).padStart(2,'0')}-${String(value.getDate()).padStart(2,'0')}`;const range=computed(()=>{const end=new Date(),start=new Date();start.setMonth(start.getMonth()-props.months);return [iso(start),iso(end)]});const option=computed<EChartsCoreOption>(()=>({tooltip:{formatter:(p:any)=>`${p.value[0]}<br/>${p.data.detail||`完成等级 ${p.value[1]}`}`},visualMap:{min:0,max:4,show:false,inRange:{color:[css('--surface-2'),css('--brand-soft'),css('--brand-line'),css('--success'),css('--brand')]}},calendar:{range:range.value,cellSize:['auto',18],splitLine:{show:false},itemStyle:{borderWidth:3,borderColor:css('--surface')},dayLabel:{color:css('--text-3'),fontSize:11},monthLabel:{color:css('--text-2'),fontSize:12},yearLabel:{show:false}},series:[{type:'heatmap',coordinateSystem:'calendar',data:props.data.map(row=>({value:[row.date,row.level],detail:row.detail}))}]}))
</script><template><ChartBase :option="option" :height="height" :empty="!data.length" empty-text="还没有训练记录" @click="(p:any)=>emit('select',p.value[0])"/></template>
